mapper.select:
SELECT available_balance
FROM wallets
WHERE user_id = #{userId}

SELECT locked_balance
FROM wallets
WHERE user_id = #{userId}

SELECT id
FROM wallets
WHERE user_id = #{userId}
  AND currency = #{currency}

mapper.update:
UPDATE wallets
SET available_balance = #{availableAfter},
    locked_balance    = #{lockedAfter},
    updated_at        = NOW(6)
WHERE id = #{walletId}
  AND currency = #{currency}
  AND available_balance = #{availableBefore}
  AND locked_balance = #{lockedBefore}

UPDATE wallets
SET available_balance = available_balance - #{amount},
    updated_at        = NOW(6)
WHERE user_id = #{userId}
  AND available_balance >= #{amount}

UPDATE wallets
SET available_balance = available_balance - #{amount},
    locked_balance    = locked_balance + #{amount},
    updated_at        = NOW(6)
WHERE user_id = #{userId}
  AND available_balance >= #{amount}

UPDATE wallets
SET locked_balance = locked_balance - #{amount},
    updated_at     = NOW(6)
WHERE user_id = #{userId}
  AND locked_balance >= #{amount}

mapper.select:
SELECT COUNT(*)
FROM wallet_transactions
WHERE idempotency_key = #{idempotencyKey}

SELECT 
FROM wallet_transactions wt
JOIN wallets w ON w.id = wt.wallet_id
WHERE wt.idempotency_key = #{idempotencyKey}
  AND wt.transaction_type = 'FUNDING'
  AND wt.work_case_id IS NULL
  AND wt.reference_type = 'FUNDING_ORDER'
  AND wt.reference_id = #{fundingOrderId}
  AND wt.wallet_id = #{walletId}
FOR SHARE OF wt
